const { createCollector } = require('./helper');

// ============================================================================
// Korean particle (조사) helpers for natural, grammatically smooth questions
// ============================================================================
function stripTrailingPunct(str) {
  return String(str || '').replace(/[)"'》」』\s]+$/g, '');
}

function hasBatchim(str) {
  const s = stripTrailingPunct(str);
  if (!s) return false;
  const code = s.charCodeAt(s.length - 1);
  if (code >= 0xac00 && code <= 0xd7a3) {
    return (code - 0xac00) % 28 !== 0;
  }
  return false;
}

function isRieul(str) {
  const s = stripTrailingPunct(str);
  if (!s) return false;
  const code = s.charCodeAt(s.length - 1);
  if (code >= 0xac00 && code <= 0xd7a3) {
    return (code - 0xac00) % 28 === 8;
  }
  return false;
}

const jEun = (w) => `${w}${hasBatchim(w) ? '은' : '는'}`;
const jI = (w) => `${w}${hasBatchim(w) ? '이' : '가'}`;
const jEul = (w) => `${w}${hasBatchim(w) ? '을' : '를'}`;
const jGwa = (w) => `${w}${hasBatchim(w) ? '과' : '와'}`;
const jEuro = (w) => `${w}${!hasBatchim(w) || isRieul(w) ? '로' : '으로'}`;
const jRago = (w) => `${w}${hasBatchim(w) ? '이라는' : '라는'}`;

function excludeItems(pool, excluded) {
  if (!excluded || excluded.length === 0) return pool;
  const ex = new Set(excluded);
  return pool.filter((item) => !ex.has(item));
}

function bumpDiff(diff) {
  if (diff === 'intro') return 'beginner';
  if (diff === 'beginner') return 'intermediate';
  return 'advanced';
}

function lowerDiff(diff) {
  if (diff === 'advanced') return 'intermediate';
  if (diff === 'intermediate') return 'beginner';
  return 'intro';
}

