  ['티베트 문자', '아부기다', '7세기 토번 왕조의 송첸감포 왕 시기 인도 굽타 계통 문자를 바탕으로 불경 번역을 위해 만든 문자', 'advanced'],
  ['점자', '촉각 표기 체계', '19세기 프랑스 루이 브라유가 고안하여 6개의 돌출된 점의 조합으로 시각장애인이 손끝으로 읽는 문자', 'intro']
