  ['고립어', '단어의 형태 변화가 거의 없이 어순과 독립된 기능어만으로 문법 관계를 나타내는 언어 유형으로 중국어와 베트남어가 대표적', 'intermediate'],
  ['굴절어', '단어 어미 하나에 성·수·격·시제 등 여러 문법 정보가 융합되어 어형 변화가 일어나는 언어 유형으로 라틴어·러시아어·독일어가 대표적', 'intermediate'],
  ['포합어', '주어·목적어·동사 등 한 문장 전체의 요소가 하나의 긴 복합 단어 안에 결합되는 언어 유형으로 이누이트어 등이 대표적', 'advanced']
